  add(/количество вещества|молярная масса|расчеты по формулам|взаимосвязь количества|моль(?![а-я])/, "n = m/M;  N = n·N_A;  M = Mr г/моль", r => { const f = pk(r, subs.slice(0, 10)), m = pk(r, [9, 18, 36, 44, 88, 100, 200]); return [`Найдите количество вещества, которое содержится в ${m} г вещества ${fm(f)}.`, `M(${fm(f)}) = ${nf(Mr(f))} г/моль; n = m/M = ${m}/${nf(Mr(f))} = ${nf(m / Mr(f))} моль.`]; }, r => { const f = pk(r, ["H2O", "CO2", "NaCl", "Fe", "Cu"]), n = pk(r, [0.5, 2, 3, 0.25]); const M = f === "Fe" ? 56 : f === "Cu" ? 64 : Mr(f); return [`Какая масса вещества ${fm(f)} соответствует количеству вещества ${num(n)} моль? Сколько в этой порции структурных единиц (N_A = 6·10²³ моль⁻¹)?`, `m = nM = ${num(n)}·${nf(M)} = ${nf(n * M)} г; N = n·N_A = ${num(n)}·6·10²³ = ${nf(n * 6e23)}.`]; }, r => { const m = pk(r, [9, 18, 36, 54]); return [`Сколько атомов кислорода содержится в ${m} г воды?`, `n(H₂O) = ${m}/18 = ${nf(m / 18)} моль; N(молекул) = ${nf(m / 18 * 6e23)}; в молекуле один атом O, поэтому N(O) = ${nf(m / 18 * 6e23)}.`]; });
  add(/валентность|бинарн/, "формула по валентностям: A(a)B(b) → A_{b/НОД} B_{a/НОД}", r => { const [A, a, nA, B, b, nB] = pk(r, [["Al", 3, "алюминия", "O", 2, "оксид"], ["Ca", 2, "кальция", "Cl", 1, "хлорид"], ["Na", 1, "натрия", "S", 2, "сульфид"], ["Mg", 2, "магния", "N", 3, "нитрид"], ["Fe", 3, "железа (III)", "Cl", 1, "хлорид"], ["Zn", 2, "цинка", "O", 2, "оксид"], ["P", 5, "фосфора (V)", "O", 2, "оксид"], ["Si", 4, "кремния (IV)", "O", 2, "оксид"]]); const gcd = (x, y) => y ? gcd(y, x % y) : x, d = gcd(a, b); const i = b / d, j = a / d; return [`Составьте формулу соединения: ${nB} ${nA} (валентность ${A} равна ${a}, ${B} равна ${b}).`, `Наименьшее общее кратное ${a * b / d}; индексы: ${A}${i > 1 ? sub(i) : ""}${B}${j > 1 ? sub(j) : ""} – проверка: ${a}·${i} = ${b}·${j}.`]; }, r => { const [f, x] = pk(r, [["SO3", "S"], ["P2O5", "P"], ["Fe2O3", "Fe"], ["Cl2O7", "Cl"], ["N2O5", "N"]]); const a = atoms(f), o = a.O, k = Object.keys(a).find(y => y !== "O"); return [`Определите валентность элемента ${k} в оксиде ${fm(f)} (валентность кислорода II).`, `${a[k]}·x = ${o}·2 → x = ${nf(o * 2 / a[k])}; валентность ${k} равна ${nf(o * 2 / a[k])}.`]; }, r => { const f = pk(r, ["Al2O3", "Fe2O3", "P2O5"]); return [`Вычислите массовую долю кислорода в ${fm(f)} и массу кислорода в 51 г этого вещества (для ${fm(f)} с Mr = ${nf(Mr(f))}).`, `ω(O) = ${atoms(f).O * 16}/${nf(Mr(f))} = ${nf(atoms(f).O * 16 / Mr(f) * 100)} %; m(O) = ${nf(51 * atoms(f).O * 16 / Mr(f))} г.`]; });
  add(/закон сохранения массы/, "m(реагентов) = m(продуктов)", r => { const m1v = pk(r, [12, 24, 6]); const m2v = m1v * 40 / 24; return [`Магний массой ${m1v} г сгорел в кислороде, образовалось ${nf(m2v)} г оксида магния. Какая масса кислорода прореагировала?`, `m(O₂) = m(MgO) − m(Mg) = ${nf(m2v)} − ${m1v} = ${nf(m2v - m1v)} г (закон сохранения массы).`]; }, r => { const m = pk(r, [21.7, 43.4, 10.85]); const hg = m * 200.5 / 216.5; return [`При разложении ${num(m)} г оксида ртути (II) образовалось ${nf(hg)} г ртути. Найдите массу выделившегося кислорода.`, `m(O₂) = ${num(m)} − ${nf(hg)} = ${nf(m - hg)} г.`]; }, r => byEq(r, poolOf(ALL, /^Mg$/, /Mg/), "mass"));
  add(/химические уравнения|расстановка коэффициентов/, "число атомов каждого элемента слева = справа", ...(() => { const B = [["Al + O2 = Al2O3", "4Al + 3O2 = 2Al2O3"], ["Fe + Cl2 = FeCl3", "2Fe + 3Cl2 = 2FeCl3"], ["H2 + N2 = NH3", "3H2 + N2 = 2NH3"], ["CH4 + O2 = CO2 + H2O", "CH4 + 2O2 = CO2 + 2H2O"], ["Na + H2O = NaOH + H2", "2Na + 2H2O = 2NaOH + H2"], ["KClO3 = KCl + O2", "2KClO3 = 2KCl + 3O2"], ["P + O2 = P2O5", "4P + 5O2 = 2P2O5"], ["Fe2O3 + H2 = Fe + H2O", "Fe2O3 + 3H2 = 2Fe + 3H2O"], ["Al + HCl = AlCl3 + H2", "2Al + 6HCl = 2AlCl3 + 3H2"], ["C2H6 + O2 = CO2 + H2O", "2C2H6 + 7O2 = 4CO2 + 6H2O"], ["Ca(OH)2 + H3PO4 = Ca3(PO4)2 + H2O", "3Ca(OH)2 + 2H3PO4 = Ca3(PO4)2 + 6H2O"], ["Mg + O2 = MgO", "2Mg + O2 = 2MgO"]]; return [r => { const [a, b] = pk(r, B.slice(0, 6)); return [`Расставьте коэффициенты в схеме реакции: ${fmEq(parseEq(a))}.`, `${fmEq(parseEq(b))}.`]; }, r => { const [a, b] = pk(r, B.slice(6, 9)); return [`Расставьте коэффициенты и определите тип реакции: ${fmEq(parseEq(a))}.`, `${fmEq(parseEq(b))}.`]; }, r => { const [a, b] = pk(r, B.slice(9)); return [`Расставьте коэффициенты в более сложной схеме: ${fmEq(parseEq(a))}. Сумма коэффициентов в правой части?`, `${fmEq(parseEq(b))}; сумма коэффициентов в правой части = ${parseEq(b).r.reduce((s, x) => s + x[0], 0)}.`]; }]; })());
  add(/классификация химических реакций: соединения|классификация химических реакций по различным/, "соединение A + B → AB;  разложение AB → A + B;  замещение A + BC → AC + B;  обмен AB + CD → AD + CB", ...(() => { const T = [["2Mg + O2 = 2MgO", "соединения"], ["CaCO3 = CaO + CO2", "разложения"], ["Zn + 2HCl = ZnCl2 + H2", "замещения"], ["CuSO4 + 2NaOH = Cu(OH)2 + Na2SO4", "обмена"], ["2H2O2 = 2H2O + O2", "разложения"], ["Fe + CuSO4 = FeSO4 + Cu", "замещения"], ["CaO + H2O = Ca(OH)2", "соединения"], ["NaOH + HCl = NaCl + H2O", "обмена"]]; const mk = i => r => { const [e, t] = pk(r, T.slice(i, i + 4)); return [`Определите тип реакции по числу и составу реагентов и продуктов: ${fmEq(parseEq(e))}.`, `Реакция ${t}.`]; }; return [mk(0), mk(2), mk(4)]; })());
  add(/молярный объем|объемных отношений|реакций с участием газов|газов/, "n = V/Vₘ;  V = n·Vₘ (Vₘ = 22,4 л/моль при н. у.);  D(H₂) = M/2;  D(возд.) = M/29", r => { const f = pk(r, ["H2", "O2", "CO2", "N2", "NH3", "CH4"]), V = pk(r, [11.2, 22.4, 44.8, 67.2, 5.6]); return [`Какова масса ${num(V)} л газа ${fm(f)} (н. у.)? Сколько это молей?`, `n = V/Vₘ = ${num(V)}/22,4 = ${nf(V / 22.4)} моль; m = nM = ${nf(V / 22.4)}·${nf(Mr(f))} = ${nf(V / 22.4 * Mr(f))} г.`]; }, r => byEq(r, poolOf(GASP, /H2$/), "vol"), r => { const f = pk(r, ["CO2", "NH3", "SO2", "O2", "Cl2"]); return [`Найдите относительную плотность газа ${fm(f)} по водороду и по воздуху.`, `D(H₂) = ${nf(Mr(f))}/2 = ${nf(Mr(f) / 2)}; D(возд.) = ${nf(Mr(f))}/29 = ${nf(Mr(f) / 29)}.`]; });
  add(/^(?!.*(?:примес|избыт|выход)).*(?:расчеты по уравнениям|расчетных? задач[аи]? по уравнениям|по уравнениям химических реакций)/, "n(А)/a = n(В)/b;  m = nM;  V = nVₘ", r => byEq(r, INORG, "mass"), r => byEq(r, GASP, "vol"), r => { const e = m1(r, SALT.length ? SALT : INORG), A = e.l[0], B = e.r.find(x => x[1] !== "H2O" && !GAS.has(x[1])) || e.r[0]; const MA = Mr(A[1]), m = pk(r, [20, 40, 80, 100]), w = pk(r, [10, 20, 25, 40]), nA = m * w / 100 / MA, nB = nA * B[0] / A[0]; return [`Раствор вещества ${fm(A[1])} массой ${m} г с массовой долей ${w} % вступил в реакцию ${fmEq(e)}. Найдите массу вещества ${fm(B[1])}, которое получилось.`, `m(${fm(A[1])}) = ${nf(m * w / 100)} г; n = ${nf(nA)} моль; n(${fm(B[1])}) = ${nf(nB)} моль; m = ${nf(nB * Mr(B[1]))} г.`]; });
  add(/массовая доля растворенного вещества|растворы|раствор/, "ω = m(в-ва)/m(р-ра) · 100 %;  m(р-ра) = m(в-ва) + m(воды)", ...solutionLv);
  add(/избытке|избыток/, "n(А)/a и n(В)/b: меньшее — недостаток, по нему считают продукт", r => { const e = m1(r, [1, 22, 23, 12, 14]), A = e.l[0], B = e.l[1]; const mA = pk(r, [13, 26, 6.5, 24, 12]), mB = pk(r, [18.25, 36.5, 73, 20, 40]); const nA = mA / Mr(A[1]) / A[0], nB = mB / Mr(B[1]) / B[0], low = nA < nB ? A : B, C = e.r[0]; const nC = Math.min(nA, nB) * C[0]; return [`Смешали ${num(mA)} г вещества ${fm(A[1])} и ${num(mB)} г вещества ${fm(B[1])} (реакция ${fmEq(e)}). Какое вещество в избытке? Найдите массу вещества ${fm(C[1])}.`, `n(${fm(A[1])})/${A[0]} = ${nf(nA)}; n(${fm(B[1])})/${B[0]} = ${nf(nB)}; в недостатке ${fm(low[1])}, в избытке ${fm((nA < nB ? B : A)[1])}; m(${fm(C[1])}) = ${nf(nC)}·${nf(Mr(C[1]))} = ${nf(nC * Mr(C[1]))} г.`]; });
  add(/выход|примес/, "η = m(практ.)/m(теор.)·100 %;  m(в-ва) = m(смеси)·(1 − ω(примесей))", r => { const e = m1(r, [12, 3, 18, 14, 26]), A = e.l[0], B = e.r.find(x => !GAS.has(x[1])) || e.r[0], m = pk(r, [50, 100, 200]), eta = pk(r, [75, 80, 85, 90]); const th = m / Mr(A[1]) * B[0] / A[0] * Mr(B[1]); return [`Из ${m} г вещества ${fm(A[1])} по реакции ${fmEq(e)} получили вещество ${fm(B[1])}. Практический выход составил ${eta} %. Найдите массу полученного вещества ${fm(B[1])}.`, `Теоретический выход m(${fm(B[1])}) = ${nf(th)} г; практический = ${nf(th)}·${eta}/100 = ${nf(th * eta / 100)} г.`]; }, r => { const m = pk(r, [100, 200, 500]), w = pk(r, [80, 90, 95]); const V = m * w / 100 / 100 * VM; return [`Известняк массой ${m} г с массовой долей CaCO₃ ${w} % обработали избытком соляной кислоты. Какой объём углекислого газа (н. у.) выделился?`, `m(CaCO₃) = ${nf(m * w / 100)} г; n = ${nf(m * w / 100 / 100)} моль; V(CO₂) = n·Vₘ = ${nf(V)} л.`]; }, r => { const e = m1(r, [3, 12, 22, 16]), A = e.l[0], B = e.r[0], m = pk(r, [25, 50, 100]), w = pk(r, [4, 5, 10, 20]); const MA = Mr(A[1]), mp = m * (100 - w) / 100, th = mp / MA * e.r.find(x => !GAS.has(x[1]) && x[1] !== "H2O")?.[0] / A[0] * Mr(e.r.find(x => !GAS.has(x[1]) && x[1] !== "H2O")[1]); const T = e.r.find(x => !GAS.has(x[1]) && x[1] !== "H2O") || B; return [`Образец вещества ${fm(A[1])} массой ${m} г содержит ${w} % примесей. Найдите массу вещества ${fm(T[1])}, получившегося по уравнению ${fmEq(e)}.`, `m(чистого ${fm(A[1])}) = ${m}·${100 - w}/100 = ${nf(mp)} г; n = ${nf(mp / MA)} моль; m(${fm(T[1])}) = ${nf(mp / MA * T[0] / A[0] * Mr(T[1]))} г.`]; });
