  addG([8, 9, 11], /степень окисления|окислительно-восстановительн|электронного баланса/, "Σ степеней окисления в молекуле = 0;  H +1, O −2, щелочные металлы +1", ...(() => { const O = [["H2SO4", "S"], ["SO2", "S"], ["HNO3", "N"], ["NH3", "N"], ["KMnO4", "Mn"], ["K2Cr2O7", "Cr"], ["Na2SO3", "S"], ["H3PO4", "P"], ["CaCO3", "C"], ["CH4", "C"], ["Fe2O3", "Fe"], ["HClO3", "Cl"], ["NO2", "N"], ["H2S", "S"]]; const KN = { H: 1, O: -2, Na: 1, K: 1, Ca: 2 }; const st = (f, el) => { const a = atoms(f); let s = 0; for (const k in a) if (k !== el) s += KN[k] * a[k]; return -s / a[el]; }; const sg = x => (x > 0 ? "+" : x < 0 ? "−" : "") + Math.abs(x); const mk = (i, j) => r => { const [f, el] = pk(r, O.slice(i, j)); const x = st(f, el); return [`Определите степень окисления элемента ${el} в соединении ${fm(f)}.`, `Сумма степеней окисления равна нулю; степень окисления ${el} = ${sg(x)}.`]; }; return [mk(0, 5), mk(5, 10), r => { const e = pk(r, [["Zn + CuSO4 = ZnSO4 + Cu", "Zn", "Cu"], ["Fe + CuSO4 = FeSO4 + Cu", "Fe", "Cu"], ["2Mg + O2 = 2MgO", "Mg", "O"]]); return [`В реакции ${fmEq(parseEq(e[0]))} укажите окислитель и восстановитель.`, `Восстановитель – ${e[1]} (отдаёт электроны, степень окисления повышается от 0 до +2); окислитель – ${e[2]}${e[2] === "O" ? "₂" : "²⁺"} (принимает электроны).`]; }]; })());
