    const probs = probsOf(p, 3), hwp = probsOf(p, 3, "hw"), Q = qualOf(p, kind, terms), fo = formulasOf(p, kind), acts = actsOf(F), lab = kind === "lab" ? labOf(p) : null, eqs = eqsOf(p), opyt = labOpyt(p);
    if (/^Организационный/.test(st)) return { t: kind === "lab" ? "Приветствует класс, проверяет готовность: халаты, очки, реактивы и оборудование на столах по списку, тетрадь, ручка. Напоминает: работа в парах, реактивы брать только по разрешению." : "Приветствует класс, проверяет готовность: учебник, тетрадь, таблицы Периодическая система, растворимость, ряд активности; демонстрационный стол подготовлен.", s: "Настраиваются на работу, проверяют рабочее место.", u: "Регулятивные: самоорганизация." };
